// node third-party/react-vendor/build.mjs — regenerate committed ESM wrappers.
//
// Why: React's dev CJS hides every `exports.X =` inside
// `"production" !== process.env.NODE_ENV && (function(){...})()`, which is
// opaque to static analysis (cjs-module-lexer, esbuild, rolldown). Every
// bundler therefore emits default-only output, StrictMode etc. come back
// undefined, and React unmounts the whole tree silently.
//
// Fix: no bundler at all. The CJS evaluates fine at runtime; the wrapper is
// `prelude + original source + named-export footer`. Export names are ground
// truth from Node require(), and the script fails loudly on shape changes.
// Rerun after every react upgrade.
import { createRequire } from 'node:module'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const NM = join(HERE, '..', '..', 'node_modules')
const require = createRequire(join(NM, 'react', 'package.json'))

const fail = message => {
  console.error(`build.mjs: ${message}`)
  process.exit(1)
}

// source CJS dev file -> [wrapper file, sibling imports]
// Sibling imports use BARE specifiers ('react', not './react.mjs') on purpose:
// the optimizer bundles id 'react' anyway (see README), so every consumer must
// resolve to that same chunk. Relative imports would load a second copy of
// React straight from source (two instances -> hooks break).
const ENTRIES = {
  'react.mjs': ['react/cjs/react.development.js', {}],
  'react-dom.mjs': ['react-dom/cjs/react-dom.development.js', { react: 'react' }],
  'react-dom-client.mjs': ['react-dom/cjs/react-dom-client.development.js', { react: 'react', 'react-dom': 'react-dom', scheduler: './scheduler.mjs' }],
  'react-jsx-runtime.mjs': ['react/cjs/react-jsx-runtime.development.js', { react: 'react' }],
  'react-jsx-dev-runtime.mjs': ['react/cjs/react-jsx-dev-runtime.development.js', { react: 'react' }],
  'scheduler.mjs': ['scheduler/cjs/scheduler.development.js', {}],
  // CJS transitive dep of the (excluded, source-served) ketcher/codemirror chain:
  // served raw to the browser it exposes no named exports; same treatment.
  'subscription.mjs': ['subscription/index.js', {}],
}

for (const [out, [src, siblings]] of Object.entries(ENTRIES)) {
  const file = join(NM, src)
  let code = readFileSync(file, 'utf8')
  code = code.replace(/\/\/# sourceMappingURL=.*$/m, '')
  if (/^\s*(import|export)\s/m.test(code)) {
    fail(`${out}: source looks like ESM, converter assumptions broken`)
  }

  // Ground truth: evaluate the real CJS in Node.
  const mod = require(join(NM, src))
  const names = Object.keys(mod)
  if (names.length === 0) fail(`${out}: no exports at runtime`)
  for (const name of names) {
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name)) fail(`${out}: unexportable name ${JSON.stringify(name)}`)
  }

  // Rewrite require("x") -> sibling namespace identifier.
  const used = new Map()
  code = code.replace(/require\(("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')\)/g, (match, quoted) => {
    const id = JSON.parse(quoted)
    if (!(id in siblings)) fail(`${out}: unexpected require(${quoted})`)
    if (!used.has(id)) used.set(id, `__ns_${used.size}`)
    return used.get(id)
  })
  if (/\brequire\s*\(/.test(code)) fail(`${out}: residual require() call`)

  const prelude = [
    `// Generated by build.mjs from ${src}. DO NOT EDIT.`,
    ...[...used].map(([id, local]) => `import ${local} from '${siblings[id]}';`),
    'const __mod = { exports: {} };',
    'const process = { env: { NODE_ENV: "development" } };',
    '// The CJS body runs inside __init, so its `exports.X =` / `module` uses are',
    '// function-scoped and invisible to cjs-module-lexer (which only detects',
    '// top-level patterns). Bundlers then treat this file as pure ESM and keep',
    '// the named exports below instead of collapsing to default-only interop.',
    'function __init(module, exports) {',
  ].join('\n')

  const footer = [
    '}',
    '__init(__mod, __mod.exports);',
    'const __ns = __mod.exports;',
    'export default __ns;',
    `export const { ${names.join(', ')} } = __ns;`,
  ].join('\n')

  writeFileSync(join(HERE, out), `${prelude}\n${code}\n${footer}\n`)
  console.log(`wrote ${out} (${names.length} named exports)`)
}
for (const [out, [src]] of Object.entries(ENTRIES)) {
  const expected = require(join(NM, src))
  const ns = await import(pathToFileURL(join(HERE, out)).href)
  if (!('default' in ns)) fail(`${out}: missing default export`)
  const bad = Object.keys(expected).filter(k => !(k in ns) || typeof ns[k] !== typeof expected[k])
  if (bad.length > 0) fail(`${out}: missing/mismatched exports: ${bad.join(', ')}`)
  console.log(`ok ${out}`)
}
